<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('resources/index.php');verify_csrf();$id=(int)($_POST['resource_id']??0);$user=(int)current_user()['user_id'];$st=$pdo->prepare('SELECT saved_resource_id FROM saved_resources WHERE user_id=? AND resource_id=?');$st->execute([$user,$id]);if($st->fetchColumn()){$st=$pdo->prepare('DELETE FROM saved_resources WHERE user_id=? AND resource_id=?');$st->execute([$user,$id]);flash('Resource removed from saved items.','info');}else{$st=$pdo->prepare('INSERT IGNORE INTO saved_resources (user_id,resource_id) VALUES (?,?)');$st->execute([$user,$id]);flash('Resource saved for later.');}redirect('resources/index.php');
